namespace hanmo::resident {namespace {
template<class T>Outcome<T> fail(const StableId& code){return {false,{},common_failure(code).error};}
bool identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
bool before(const CommonStore& c,const StableId& a,const StableId& b){const auto& o=c.state().facts.order();const auto x=std::find(o.begin(),o.end(),a),y=std::find(o.begin(),o.end(),b);return x!=o.end()&&y!=o.end()&&x<y;}
bool header(const CommonStore& c,const StableId& id,const StableId& prefix,const StableId& kind,const StableId& domain){const auto n=organization_instance_sequence(id,prefix);const auto* h=c.state().facts.find(id);return n&&*n<c.state().next_instance_id&&h&&h->id==id&&h->kind==kind&&h->domain==domain;}
bool terms_equal(const PrivateShopOrderTerms& a,const PrivateShopOrderTerms& b){return a.order_id==b.order_id&&a.shop_id==b.shop_id&&a.proprietor_actor_id==b.proprietor_actor_id&&owner_equal(a.original_client,b.original_client)&&a.task_template_id==b.task_template_id&&a.item_id==b.item_id&&a.stock_inventory_id==b.stock_inventory_id&&a.shop_wallet_id==b.shop_wallet_id&&a.client_inventory_id==b.client_inventory_id&&a.client_wallet_id==b.client_wallet_id&&a.quantity==b.quantity&&a.contract_price==b.contract_price&&a.accepted_tick==b.accepted_tick&&a.deadline_tick==b.deadline_tick;}
bool transfer_equal(const std::vector<PrivateShopOrderLotTransfer>& a,const std::vector<PrivateShopOrderLotTransfer>& b){if(a.size()!=b.size())return false;for(std::size_t n=0;n<a.size();++n)if(a[n].original_lot_id!=b[n].original_lot_id||a[n].destination_lot_id!=b[n].destination_lot_id||a[n].quantity!=b[n].quantity)return false;return true;}
// 只按该成交之前的本域永久消费事实重建成本桶；同tick后来成交不能被回填进早期成本。
Outcome<PrivateShopCostBasis> basis_before(const PrivateShopContext& x,const PrivateShopPurchaseFact& p,const StableId& boundary){PrivateShopCostBasis out{p.id,p.quantity,p.purchase_cash,0,0,0};for(const auto& f:x.common.state().facts.rows()){if(f.first==boundary)break;const std::vector<PrivateShopRetailLot>* lots=nullptr;if(const auto* day=x.state.operating_results.find(f.first))lots=&day->consumed_lots;if(const auto* order=x.state.order_settlements.find(f.first))lots=&order->consumed_lots;if(lots)for(const auto& lot:*lots)if(lot.purchase_fact_id==p.id){if(lot.quantity<=0||lot.cost<0||__builtin_add_overflow(out.sold_quantity,lot.quantity,&out.sold_quantity)||__builtin_add_overflow(out.recognized_cost,lot.cost,&out.recognized_cost))return fail<PrivateShopCostBasis>("PrivateShopCostOverflow");}}return {true,out,{}};}
Outcome<std::vector<PrivateShopRetailLot>> cost_lots(const PrivateShopContext& x,const PrivateShopOrderRecord& order,const std::vector<PrivateShopOrderLotTransfer>& transferred,const StableId& receipt,const StableId& boundary){std::map<StableId,Integer> quantities;std::set<StableId> destinations;Integer total=0;const auto receipt_number=organization_instance_sequence(receipt,"task_shop_order_settled");if(!receipt_number)return fail<std::vector<PrivateShopRetailLot>>("PrivateShopOrderTransferMismatch");for(const auto& lot:transferred){const auto original=organization_instance_sequence(lot.original_lot_id,"lot"),destination=organization_instance_sequence(lot.destination_lot_id,"lot");if(!original||!destination||*destination>=*receipt_number||*original>=*destination||lot.quantity<=0||!destinations.insert(lot.destination_lot_id).second||lot.original_lot_id==lot.destination_lot_id||__builtin_add_overflow(quantities[lot.original_lot_id],lot.quantity,&quantities[lot.original_lot_id])||__builtin_add_overflow(total,lot.quantity,&total))return fail<std::vector<PrivateShopRetailLot>>("PrivateShopOrderTransferMismatch");}if(total!=order.terms.quantity)return fail<std::vector<PrivateShopRetailLot>>("PrivateShopOrderQuantityMismatch");std::vector<PrivateShopRetailLot> out;std::map<StableId,PrivateShopCostBasis> bases;
 for(const auto& lot:quantities){const PrivateShopPurchaseFact* purchase=nullptr;Integer remaining=0;for(const auto& row:x.state.purchases.rows())if(row.second.shop_id==order.terms.shop_id&&row.second.item_id==order.terms.item_id)for(const auto& stocked:row.second.stocked_lots)if(stocked.lot_id==lot.first){if(purchase)return fail<std::vector<PrivateShopRetailLot>>("PrivateShopOrderAmbiguousCostSource");purchase=&row.second;remaining=stocked.quantity;}if(!purchase||!before(x.common,purchase->id,receipt))return fail<std::vector<PrivateShopRetailLot>>("PrivateShopOrderCostSourceMissing");for(const auto& fact:x.common.state().facts.rows()){if(fact.first==boundary)break;const std::vector<PrivateShopRetailLot>* sold=nullptr;if(const auto* day=x.state.operating_results.find(fact.first))sold=&day->consumed_lots;if(const auto* settled=x.state.order_settlements.find(fact.first))sold=&settled->consumed_lots;if(sold)for(const auto& used:*sold)if(used.lot_id==lot.first){if(used.quantity<=0||used.quantity>remaining)return fail<std::vector<PrivateShopRetailLot>>("PrivateShopOrderCostSourceOverdrawn");remaining-=used.quantity;}}if(lot.second>remaining)return fail<std::vector<PrivateShopRetailLot>>("PrivateShopOrderCostSourceOverdrawn");if(!bases.count(purchase->id)){auto b=basis_before(x,*purchase,boundary);if(!b.ok)return {false,{},b.error};bases.emplace(purchase->id,b.value);}auto& basis=bases[purchase->id];auto cost=quote_private_shop_cost_slice(basis,lot.second);if(!cost.ok)return {false,{},cost.error};out.push_back({purchase->id,lot.first,lot.second,cost.value.cost});basis.sold_quantity=cost.value.sold_quantity_after;basis.recognized_cost=cost.value.recognized_cost_after;}
 return {true,std::move(out),{}};}
Status execution_matches(const PrivateShopContext& x,const PrivateShopOrderRecord& order,const PrivateShopOrderExecution& source){const bool delivered=source.outcome=="delivered";if(!identity(source.source_identity,x.common.state().identity)||source.order_id!=order.id||source.task_id!=order.task_id||!terms_equal(source.terms,order.terms)||(source.outcome!="delivered"&&source.outcome!="cancelled")||source.completed_tick<order.terms.accepted_tick||source.refunded_price!=0||source.paid_price!=(delivered?order.terms.contract_price:0)||source.delivered_quantity!=(delivered?order.terms.quantity:0)||(!delivered&&!source.lots.empty())||(delivered&&source.completed_tick>order.terms.deadline_tick)||!organization_instance_sequence(source.settlement_id,"settlement")||!header(x.common,source.receipt_fact_id,"task_shop_order_settled","task_shop_order_settled","task_shop_orders")||!before(x.common,order.binding_fact_id,source.receipt_fact_id))return common_failure("PrivateShopOrderExecutionMismatch",order.id);return validate_private_shop_order_delivery_contact(x,order,source);}
}
Status validate_private_shop_order_settlements(const PrivateShopContext& x,bool read_task_sources){if(read_task_sources){auto contacts=validate_private_shop_order_contact_access(x);if(!contacts.ok)return contacts;}auto observed=private_shop_observed_tick(x);if(!observed.ok)return {false,{},observed.error};std::set<StableId> orders,receipts,settlements;for(const auto& row:x.state.order_settlements.rows()){const auto& s=row.second;const auto* order=x.state.orders.orders.find(s.order_id);const auto settlement=organization_instance_sequence(s.task_settlement_id,"settlement"),receipt=organization_instance_sequence(s.receipt_fact_id,"task_shop_order_settled");if(row.first!=s.id||!order||order->status!="accepted"||s.task_id!=order->task_id||s.tick<order->terms.accepted_tick||s.tick>observed.value||(s.outcome!="delivered"&&s.outcome!="cancelled")||!orders.insert(s.order_id).second||!receipts.insert(s.receipt_fact_id).second||!settlements.insert(s.task_settlement_id).second||!settlement||!receipt||*settlement>=*receipt||!header(x.common,s.id,"private_shop_order_settlement","private_shop_order_settled",private_shop_module)||!header(x.common,s.receipt_fact_id,"task_shop_order_settled","task_shop_order_settled","task_shop_orders")||!before(x.common,order->binding_fact_id,s.receipt_fact_id)||!before(x.common,s.receipt_fact_id,s.id))return common_failure("InvalidPrivateShopOrderSettlement",row.first);
  if(s.outcome=="cancelled"){if(s.income||s.cost_of_goods||!s.delivered_lots.empty()||!s.consumed_lots.empty())return common_failure("PrivateShopCancelledOrderMoneyMismatch",s.id);}else{if(s.tick>order->terms.deadline_tick||s.income!=order->terms.contract_price)return common_failure("PrivateShopOrderIncomeMismatch",s.id);auto costs=cost_lots(x,*order,s.delivered_lots,s.receipt_fact_id,s.id);if(!costs.ok)return {false,{},costs.error};if(costs.value.size()!=s.consumed_lots.size())return common_failure("PrivateShopOrderCostMismatch",s.id);Integer total=0;for(std::size_t n=0;n<costs.value.size();++n){const auto& a=costs.value[n];const auto& b=s.consumed_lots[n];if(a.purchase_fact_id!=b.purchase_fact_id||a.lot_id!=b.lot_id||a.quantity!=b.quantity||a.cost!=b.cost||__builtin_add_overflow(total,a.cost,&total))return common_failure("PrivateShopOrderCostMismatch",s.id);}if(total!=s.cost_of_goods)return common_failure("PrivateShopOrderCostMismatch",s.id);}
  if(read_task_sources){if(!x.order_execution)return common_failure("PrivateShopOrderExecutionHistoryUnavailable",s.id);auto source=x.order_execution->private_shop_order_execution(s.task_id);if(!source.ok)return {false,{},source.error};if(!source.value)return common_failure("PrivateShopOrderExecutionMissing",s.id);auto valid=execution_matches(x,*order,*source.value);if(!valid.ok)return valid;if(source.value->settlement_id!=s.task_settlement_id||source.value->receipt_fact_id!=s.receipt_fact_id||source.value->outcome!=s.outcome||source.value->completed_tick!=s.tick||!transfer_equal(source.value->lots,s.delivered_lots))return common_failure("PrivateShopOrderExecutionMismatch",s.id);}}
 return common_success();}
Outcome<StableId> capture_private_shop_order_execution_in_candidate(CommonStore& c,PrivateShopState& state,const PrivateShopContext& x,const StableId& order_id){if(&c!=&x.common||&state!=&x.state)return fail<StableId>("PrivateShopCandidateMismatch");auto contacts=validate_private_shop_order_contact_access(x);if(!contacts.ok)return {false,{},contacts.error};auto observed=private_shop_observed_tick(x);if(!observed.ok)return {false,{},observed.error};auto valid=validate_private_shop_order_ledger(x);if(!valid.ok)return {false,{},valid.error};const auto* order=state.orders.orders.find(order_id);if(!order||order->status!="accepted")return fail<StableId>("PrivateShopOrderNotAccepted");for(const auto& row:state.order_settlements.rows())if(row.second.order_id==order_id)return fail<StableId>("PrivateShopOrderAlreadySettled");if(!x.order_execution)return fail<StableId>("PrivateShopOrderExecutionHistoryUnavailable");auto source=x.order_execution->private_shop_order_execution(order->task_id);if(!source.ok)return {false,{},source.error};if(!source.value)return fail<StableId>("PrivateShopOrderExecutionMissing");valid=execution_matches(x,*order,*source.value);if(!valid.ok)return {false,{},valid.error};if(source.value->completed_tick!=observed.value)return fail<StableId>("PrivateShopOrderCaptureTickMismatch");local_economy_detail::CandidateStateGuard<PrivateShopState> guard(state);auto id=c.next_id("private_shop_order_settlement");if(!id.ok)return id;valid=c.append_fact({id.value,"private_shop_order_settled",private_shop_module});if(!valid.ok)return {false,{},valid.error};PrivateShopOrderSettlement settled;settled.id=id.value;settled.order_id=order_id;settled.task_id=order->task_id;settled.task_settlement_id=source.value->settlement_id;settled.receipt_fact_id=source.value->receipt_fact_id;settled.outcome=source.value->outcome;settled.tick=source.value->completed_tick;settled.income=source.value->paid_price;settled.delivered_lots=source.value->lots;if(settled.outcome=="delivered"){auto costs=cost_lots(x,*order,settled.delivered_lots,settled.receipt_fact_id,id.value);if(!costs.ok)return {false,{},costs.error};settled.consumed_lots=std::move(costs.value);for(const auto& lot:settled.consumed_lots)if(__builtin_add_overflow(settled.cost_of_goods,lot.cost,&settled.cost_of_goods))return fail<StableId>("PrivateShopCostOverflow");}if(!state.order_settlements.insert(id.value,settled))return fail<StableId>("PrivateShopOrderDuplicateSettlement");valid=validate_private_shops(x);if(!valid.ok)return {false,{},valid.error};guard.commit();return id;}
}
